// Parse an address like "A1" or "AA999"
export function parseAddress(addr) {
  const match = addr.match(/^([A-Z]+)(\d+)$/);
  if (!match) return null;

  const col = match[1];
  const row = parseInt(match[2], 10);

  // Column range: A-Z (1-26), AA-ZZ (27-702)
  let colNum = 0;
  for (let i = 0; i < col.length; i++) {
    colNum = colNum * 26 + (col.charCodeAt(i) - 'A'.charCodeAt(0) + 1);
  }

  // Valid ranges: columns 1-702 (A-ZZ), rows 1-999
  if (colNum < 1 || colNum > 702 || row < 1 || row > 999) {
    return null;
  }

  return { col: colNum, row, str: addr };
}

// Convert column number to letters
function colToString(col) {
  let result = '';
  while (col > 0) {
    col -= 1;
    result = String.fromCharCode('A'.charCodeAt(0) + (col % 26)) + result;
    col = Math.floor(col / 26);
  }
  return result;
}

export function addressToString(col, row) {
  return colToString(col) + row;
}

// Parse a single line of input
export function parseLine(line, lineNum) {
  // Strip leading whitespace
  const trimmed = line.replace(/^[ \t]+/, '');

  // Ignore empty lines and comments
  if (!trimmed || trimmed[0] === '#') {
    return null;
  }

  // Split address from content
  const match = trimmed.match(/^(\S+)([ \t]+|$)(.*?)$/);
  if (!match) return null;

  const addressStr = match[1];
  const content = match[3] || '';

  const addr = parseAddress(addressStr.toUpperCase());
  if (!addr) {
    return { error: `error: line ${lineNum}: invalid cell address ${addressStr}` };
  }

  return { addr, content };
}

// Tokenize a formula
export function tokenize(formula) {
  const tokens = [];
  let i = 0;

  while (i < formula.length) {
    // Skip whitespace
    if (formula[i] === ' ' || formula[i] === '\t') {
      i++;
      continue;
    }

    // Numbers (including decimals)
    if (/\d/.test(formula[i])) {
      let num = '';
      while (i < formula.length && /[\d.]/.test(formula[i])) {
        num += formula[i];
        i++;
      }
      tokens.push({ type: 'number', value: parseFloat(num) });
      continue;
    }

    // Cell addresses and identifiers
    if (/[A-Za-z]/.test(formula[i])) {
      let word = '';
      while (i < formula.length && /[A-Za-z0-9]/.test(formula[i])) {
        word += formula[i];
        i++;
      }
      word = word.toUpperCase();
      tokens.push({ type: 'word', value: word });
      continue;
    }

    // Operators and delimiters
    if (i + 1 < formula.length && (formula.substr(i, 2) === '<>' || formula.substr(i, 2) === '<=' || formula.substr(i, 2) === '>=')) {
      tokens.push({ type: 'op', value: formula.substr(i, 2) });
      i += 2;
      continue;
    }

    if ('+-*/<>=(),:'.includes(formula[i])) {
      tokens.push({ type: 'op', value: formula[i] });
      i++;
      continue;
    }

    // Unknown character
    return null;
  }

  return tokens;
}
"}

