{"file_path":"./src/types.js","content":"/**
 * Value types and utilities
 */

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'];

export class ErrorValue {
  constructor(token) {
    this.token = token;
  }

  toString() {
    return this.token;
  }
}

export class BooleanValue {
  constructor(value) {
    this.value = value;
  }

  toString() {
    return this.value ? 'TRUE' : 'FALSE';
  }
}

// Parse a literal value
export function parseLiteral(content) {
  if (!content) {
    return 0; // empty is zero
  }

  // Check for error tokens
  if (ERROR_TOKENS.includes(content)) {
    return new ErrorValue(content);
  }

  // Check for TRUE/FALSE
  if (content === 'TRUE') {
    return new BooleanValue(true);
  }
  if (content === 'FALSE') {
    return new BooleanValue(false);
  }

  // Try to parse as number
  const match = content.match(/^-?\d+(?:\.\d+)?$/);
  if (match) {
    return parseFloat(content);
  }

  // Otherwise it's text
  return content;
}

// Format a value for output
export function formatValue(value) {
  if (value instanceof ErrorValue) {
    return value.toString();
  }
  if (value instanceof BooleanValue) {
    return value.toString();
  }
  if (typeof value === 'number') {
    // Round to 10 significant digits
    let str = value.toPrecision(10);
    // Remove trailing zeros after decimal point
    str = str.replace(/\.?0+$/, '');
    return str;
  }
  return String(value);
}

// Convert value to number for arithmetic
export function toNumber(value) {
  if (value instanceof ErrorValue) {
    return value;
  }
  if (value instanceof BooleanValue) {
    return value.value ? 1 : 0;
  }
  if (typeof value === 'number') {
    return value;
  }
  if (typeof value === 'string') {
    return new ErrorValue('#VALUE!');
  }
  return 0;
}

// Convert value to boolean for conditions
export function toBoolean(value) {
  if (value instanceof ErrorValue) {
    return value;
  }
  if (value instanceof BooleanValue) {
    return value.value;
  }
  if (typeof value === 'number') {
    return value !== 0;
  }
  return false;
}

// Check if value is a number
export function isNumber(value) {
  return typeof value === 'number' || (value instanceof BooleanValue);
}

// Check if value is an error
export function isError(value) {
  return value instanceof ErrorValue;
}

// Compare two values
export function compare(a, b) {
  // Handle errors - they don't compare
  if (isError(a) || isError(b)) {
    return 0;
  }

  // Number comparisons
  const aNum = typeof a === 'number';
  const bNum = typeof b === 'number';
  const aBoolean = a instanceof BooleanValue;
  const bBoolean = b instanceof BooleanValue;

  if (aNum && bNum) {
    return a - b;
  }

  // Text comparisons
  const aText = typeof a === 'string';
  const bText = typeof b === 'string';
  if (aText && bText) {
    return a.localeCompare(b);
  }

  // Boolean comparisons
  if (aBoolean && bBoolean) {
    return (a.value ? 1 : 0) - (b.value ? 1 : 0);
  }

  // Cross-type comparisons: number < text < boolean
  if (aNum && bText) return -1;
  if (aText && bNum) return 1;
  if (aNum && bBoolean) return -1;
  if (aBoolean && bNum) return 1;
  if (aText && bBoolean) return -1;
  if (aBoolean && bText) return 1;

  // Handle booleans in number position
  if (aBoolean && bNum) {
    const aVal = a.value ? 1 : 0;
    return aVal - b;
  }
  if (aNum && bBoolean) {
    const bVal = b.value ? 1 : 0;
    return a - bVal;
  }

  return 0;
}
"}

