        case '<': result = false; break;
        case '<=': result = false; break;
        case '>': result = true; break;
        case '>=': result = true; break;
      }
    }
    // Number vs boolean: number < boolean
    else if (typeof left === 'number' && right instanceof BooleanValue) {
      switch (op) {
        case '=': result = false; break;
        case '<>': result = true; break;
        case '<': result = true; break;
        case '<=': result = true; break;
        case '>': result = false; break;
        case '>=': result = false; break;
      }
    }
    else if (left instanceof BooleanValue && typeof right === 'number') {
      switch (op) {
        case '=': result = false; break;
        case '<>': result = true; break;
        case '<': result = false; break;
        case '<=': result = false; break;
        case '>': result = true; break;
        case '>=': result = true; break;
      }
    }
    // Text vs boolean: text < boolean
    else if (typeof left === 'string' && right instanceof BooleanValue) {
      switch (op) {
        case '=': result = false; break;
        case '<>': result = true; break;
        case '<': result = true; break;
        case '<=': result = true; break;
        case '>': result = false; break;
        case '>=': result = false; break;
      }
    }
    else if (left instanceof BooleanValue && typeof right === 'string') {
      switch (op) {
        case '=': result = false; break;
        case '<>': result = true; break;
        case '<': result = false; break;
        case '<=': result = false; break;
        case '>': result = true; break;
        case '>=': result = true; break;
      }
    }
    else {
      result = false;
    }

    return new BooleanValue(result);
  }
}
