 */

import { tokenize, parseAddress, addressToString } from './parser.js';
import { ErrorValue, BooleanValue, toNumber, toBoolean, isError, isNumber, formatValue } from './types.js';

export class Evaluator {
  constructor(cells) {
    this.cells = cells; // Map of "col,row" -> { content, value, dependencies }
    this.evaluating = new Set(); // Track cells being evaluated (cycle detection)
    this.cache = new Map(); // Cache evaluated values
  }

  evaluateAll() {
    const results = new Map();

    for (const [key, cell] of this.cells) {
      const [colStr, rowStr] = key.split(',');
      const col = parseInt(colStr);
      const row = parseInt(rowStr);
      const value = this.evaluate(col, row);
      results.set(key, value);
    }

    return results;
  }

  evaluate(col, row) {
    const key = `${col},${row}`;

    if (this.cache.has(key)) {
      return this.cache.get(key);
    }

    if (this.evaluating.has(key)) {
      return new ErrorValue('#CYCLE!');
    }

    this.evaluating.add(key);

    const cell = this.cells.get(key);
    let value;

    if (!cell) {
      // Undeclared cell is 0
      value = 0;
    } else if (cell.content.startsWith('=')) {
      // Formula
      value = this.evaluateFormula(cell.content.slice(1));
    } else {
      // Literal
      const { parseLiteral } = await import('./types.js');
      value = parseLiteral(cell.content);
    }

    this.evaluating.delete(key);
    this.cache.set(key, value);
    return value;
  }

  evaluateFormula(formula) {
    const tokens = tokenize(formula);
    if (tokens === null) {
      return new ErrorValue('#ERR!');
    }

    try {
      const parser = new FormulaParser(tokens, this);
      const [result] = parser.parseComparison();

      if (parser.pos !== tokens.length) {
        return new ErrorValue('#ERR!');
      }

      return result;
    } catch (e) {
      if (e.isFormulaError) {
        return e.value;
      }
      return new ErrorValue('#ERR!');
    }
  }

  getCellValue(col, row) {
    return this.evaluate(col, row);
  }

  getRange(col1, row1, col2, row2) {
    const cells = [];
    const minCol = Math.min(col1, col2);
    const maxCol = Math.max(col1, col2);
    const minRow = Math.min(row1, row2);
    const maxRow = Math.max(row1, row2);

    for (let c = minCol; c <= maxCol; c++) {
      for (let r = minRow; r <= maxRow; r++) {
        cells.push(this.getCellValue(c, r));
      }
    }

    return cells;
  }
}

class FormulaError extends Error {
  constructor(value) {
    super();
    this.isFormulaError = true;
    this.value = value;
  }
}

class FormulaParser {
  constructor(tokens, evaluator) {
    this.tokens = tokens;
    this.evaluator = evaluator;
    this.pos = 0;
  }

  peek() {
    return this.pos < this.tokens.length ? this.tokens[this.pos] : null;
  }

  consume() {
    return this.tokens[this.pos++];
  }

  parseComparison() {
    let [left, isRange] = this.parseAddition();

    if (isRange) {
      throw new FormulaError(new ErrorValue('#ERR!'));
    }

    while (true) {
      const op = this.peek();
      if (!op || op.type !== 'op' || !['=', '<>', '<', '<=', '>', '>='].includes(op.value)) {
        break;
      }

      this.consume();
      const [right, rightIsRange] = this.parseAddition();

      if (rightIsRange) {
        throw new FormulaError(new ErrorValue('#ERR!'));
      }

      left = this.applyComparison(left, op.value, right);
    }

    return [left, false];
  }

  parseAddition() {
    let [left, isRange] = this.parseMultiplication();

    while (true) {
      const op = this.peek();
      if (!op || op.type !== 'op' || !['+', '-'].includes(op.value)) {
        break;
      }

      this.consume();
      const [right, rightIsRange] = this.parseMultiplication();

      left = this.applyOp(left, op.value, right);
      isRange = false;
    }

    return [left, isRange];
  }

  parseMultiplication() {
    let [left, isRange] = this.parseExponentiation();

    while (true) {
      const op = this.peek();
      if (!op || op.type !== 'op' || !['*', '/'].includes(op.value)) {
        break;
      }

      this.consume();
      const [right, rightIsRange] = this.parseExponentiation();

      left = this.applyOp(left, op.value, right);
      isRange = false;
    }

    return [left, isRange];
  }

  parseExponentiation() {
    let [left, isRange] = this.parseUnary();

    if (this.peek() && this.peek().type === 'op' && this.peek().value === '^') {
      this.consume();
      const [right, rightIsRange] = this.parseExponentiation(); // right associative
      left = this.applyOp(left, '^', right);
      isRange = false;
    }

    return [left, isRange];
