  parsePrimary() {
    const token = this.peek();

    if (!token) {
      throw new FormulaError(new ErrorValue('#ERR!'));
    }

    // Number
    if (token.type === 'number') {
      this.consume();
      return [token.value, false];
    }

    // Word (identifier, function, or cell reference)
    if (token.type === 'word') {
