        const addr1 = parseAddress(word);
        if (!addr1) {
          throw new FormulaError(new ErrorValue('#ERR!'));
        }

        this.consume(); // consume ':'
        const token2 = this.peek();
        if (!token2 || token2.type !== 'word') {
          throw new FormulaError(new ErrorValue('#ERR!'));
        }

        this.consume();
        const addr2 = parseAddress(token2.value);
        if (!addr2) {
          throw new FormulaError(new ErrorValue('#ERR!'));
        }

        return [{ type: 'range', addr1, addr2 }, true];
