{"file_path":"src/values.js","content":"/**
 * Cell values: numbers, text, booleans and errors, and the operations the
 * spreadsheet language performs on them.
 */

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export class ErrorValue {
  constructor(token) {
    this.token = token
  }
}

export class BoolValue {
  constructor(value) {
    this.value = value
  }
}

export const TRUE = new BoolValue(true)
export const FALSE = new BoolValue(false)

export const DIV0 = new ErrorValue('#DIV/0!')
export const REF = new ErrorValue('#REF!')
export const VALUE = new ErrorValue('#VALUE!')
export const CYCLE = new ErrorValue('#CYCLE!')
export const NAME = new ErrorValue('#NAME?')
export const ERR = new ErrorValue('#ERR!')

export function isError(value) {
  return value instanceof ErrorValue
}

export function isBool(value) {
  return value instanceof BoolValue
}

export function isNumber(value) {
  return typeof value === 'number'
}

export function isText(value) {
  return typeof value === 'string'
}

const NUMBER_LITERAL = /^-?[0-9]+(?:\.[0-9]+)?$/

/** Read the content of a cell that is not a formula. */
export function parseLiteral(content) {
  if (content === '') return 0
  if (ERROR_TOKENS.includes(content)) return new ErrorValue(content)
  if (NUMBER_LITERAL.test(content)) return Number(content)
  return content
}

/** Read a value in a position that wants a number. */
export function toNumber(value) {
  if (isError(value)) return value
  if (isNumber(value)) return value
  if (isBool(value)) return value.value ? 1 : 0
  return VALUE
}

/** Guard an arithmetic result: anything not finite is a division error. */
export function finite(result) {
  return Number.isFinite(result) ? result : DIV0
}

/** Read a value in a position that wants a condition. */
export function toCondition(value) {
  if (isError(value)) return value
  if (isBool(value)) return value.value
  if (isNumber(value)) return value !== 0
  return VALUE
}

function kindRank(value) {
  if (isNumber(value)) return 0
  if (isText(value)) return 1
  return 2
}

function compareText(a, b) {
  const left = Array.from(a)
  const right = Array.from(b)
  const shared = Math.min(left.length, right.length)
  for (let i = 0; i < shared; i++) {
    const x = left[i].codePointAt(0)
    const y = right[i].codePointAt(0)
    if (x !== y) return x < y ? -1 : 1
  }
  if (left.length === right.length) return 0
  return left.length < right.length ? -1 : 1
}

/** Order two non-error values: numbers, then texts, then booleans. */
export function compareValues(a, b) {
  const ra = kindRank(a)
  const rb = kindRank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (ra === 0) return a === b ? 0 : a < b ? -1 : 1
  if (ra === 1) return compareText(a, b)
  const x = a.value ? 1 : 0
  const y = b.value ? 1 : 0
  return x === y ? 0 : x < y ? -1 : 1
}

function formatNumber(n) {
  const rounded = Number(n.toPrecision(10))
  if (rounded === 0) return '0'
  return String(rounded)
}

/** Render a value the way the `values` mode prints it. */
export function formatValue(value) {
  if (isError(value)) return value.token
  if (isBool(value)) return value.value ? 'TRUE' : 'FALSE'
  if (isNumber(value)) return formatNumber(value)
  return value
}
"}

