{"file_path":"src/address.js","content":"/**
 * Cell addresses: one or two letters naming a column and one to three digits
 * naming a row of at least one.
 */

const ADDRESS = /^([A-Z]{1,2})([0-9]{1,3})$/

/**
 * Read an address, already upper-cased. Returns { col, row } with one-based
 * numbers, or null when the text does not name a cell in range.
 */
export function parseAddress(text) {
  const match = ADDRESS.exec(text)
  if (match === null) return null
  const letters = match[1]
  let col = 0
  for (const ch of letters) col = col * 26 + (ch.charCodeAt(0) - 64)
  const row = Number(match[2])
  if (row < 1) return null
  return { col, row }
}

/** Render a column number as its letters. */
export function columnName(col) {
  let n = col
  let name = ''
  while (n > 0) {
    n -= 1
    name = String.fromCharCode(65 + (n % 26)) + name
    n = Math.floor(n / 26)
  }
  return name
}

export function formatAddress(col, row) {
  return columnName(col) + row
}

export function cellKey(col, row) {
  return col + ':' + row
}
"}

