  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.pos < this.tokens.length ? this.tokens[this.pos] : null
  }

  isOp(value) {
    const token = this.peek()
    return token !== null && token.type === 'op' && token.value === value
  }

  next() {
    if (this.pos >= this.tokens.length) throw new ParseFailure()
    return this.tokens[this.pos++]
  }

  expectOp(value) {
    if (!this.isOp(value)) throw new ParseFailure()
    this.pos += 1
  }

