    let left = this.parseAdditive()
    while (true) {
      const token = this.peek()
      if (token === null || token.type !== 'op' || !COMPARISONS.includes(token.value)) break
      this.pos += 1
      const right = this.parseAdditive()
      left = { type: 'compare', op: token.value, left, right }
    }
