      const args = []
      if (this.isOp(')')) {
        this.pos += 1
      } else {
        while (true) {
          args.push(this.parseExpression())
          if (this.isOp(',')) {
            this.pos += 1
            continue
          }
          this.expectOp(')')
          break
        }
      }
      return { type: 'call', name: word, args }
    }
    if (this.isOp(':')) {
      this.pos += 1
      const end = this.next()
      if (end.type !== 'word') throw new ParseFailure()
      return { type: 'range', from: word, to: end.value }
    }
