export function tokenize(body) {
  const tokens = []
  let i = 0
  while (i < body.length) {
    const ch = body[i]
    if (ch === ' ' || ch === '\t') {
      i += 1
      continue
    }
    if (ch >= '0' && ch <= '9') {
      let j = i
      while (j < body.length && body[j] >= '0' && body[j] <= '9') j += 1
      if (body[j] === '.') {
        const start = j + 1
        let k = start
        while (k < body.length && body[k] >= '0' && body[k] <= '9') k += 1
        if (k === start) return null
        j = k
      }
      tokens.push({ type: 'number', value: Number(body.slice(i, j)) })
      i = j
      continue
    }
    if (isLetter(ch)) {
      let j = i
      while (j < body.length && (isLetter(body[j]) || (body[j] >= '0' && body[j] <= '9'))) j += 1
      tokens.push({ type: 'word', value: body.slice(i, j).toUpperCase() })
      i = j
      continue
    }
    const two = body.slice(i, i + 2)
    if (two === '<>' || two === '<=' || two === '>=') {
      tokens.push({ type: 'op', value: two })
      i += 2
      continue
    }
    if ('+-*/^=<>(),:'.includes(ch)) {
      tokens.push({ type: 'op', value: ch })
      i += 1
      continue
    }
    return null
  }
  return tokens
