{"file_path":"src/evaluator.js","content":"/**
 * Evaluation of a sheet: each cell's value, computed on demand, with cells
 * that reach themselves reported as cycles.
 */

import { cellKey } from './address.js'
import { parseFormula, rangeCells } from './formula.js'
import {
  BoolValue,
  CYCLE,
  DIV0,
  ERR,
  NAME,
  REF,
  compareValues,
  finite,
  isError,
  isNumber,
  parseLiteral,
  toCondition,
  toNumber
} from './values.js'

const ARITY = {
  SUM: null,
  MIN: null,
  MAX: null,
  COUNT: null,
  AVG: null,
  ABS: 1,
  IF: 3
}

export class Sheet {
  /** @param cells Map of cell key to { col, row, content } */
  constructor(cells) {
    this.cells = cells
    this.cache = new Map()
    this.active = new Set()
    this.trees = new Map()
  }

  /** The tree of a cell's formula, or null for a literal or a bad formula. */
  treeOf(cell) {
    const key = cellKey(cell.col, cell.row)
    if (!this.trees.has(key)) {
      this.trees.set(key, cell.content.startsWith('=') ? parseFormula(cell.content.slice(1)) : null)
    }
    return this.trees.get(key)
  }

  valueAt(col, row) {
    const key = cellKey(col, row)
    if (this.cache.has(key)) return this.cache.get(key)
    if (this.active.has(key)) return CYCLE
    const cell = this.cells.get(key)
    if (cell === undefined) return 0
    this.active.add(key)
    let value
    if (cell.content.startsWith('=')) {
      const tree = this.treeOf(cell)
      value = tree === null ? ERR : this.evaluate(tree)
    } else {
      value = parseLiteral(cell.content)
    }
    this.active.delete(key)
    this.cache.set(key, value)
    return value
  }

  evaluate(node) {
    switch (node.type) {
      case 'number':
        return node.value
      case 'boolean':
        return new BoolValue(node.value)
      case 'group':
        return this.evaluate(node.inner)
      case 'ref':
        return node.address === null ? REF : this.valueAt(node.address.col, node.address.row)
      case 'range':
        // A range is only a value where it stands directly as an argument.
        return ERR
      case 'unary':
        return this.evaluateUnary(node)
      case 'binary':
        return this.evaluateBinary(node)
      case 'compare':
        return this.evaluateComparison(node)
      case 'call':
        return this.evaluateCall(node)
      default:
        return ERR
    }
  }

  evaluateUnary(node) {
    const operand = toNumber(this.evaluate(node.operand))
    if (isError(operand)) return operand
    return node.op === '-' ? finite(-operand) : operand
  }

  evaluateBinary(node) {
    const left = toNumber(this.evaluate(node.left))
    if (isError(left)) return left
    const right = toNumber(this.evaluate(node.right))
    if (isError(right)) return right
    switch (node.op) {
      case '+':
        return finite(left + right)
      case '-':
        return finite(left - right)
      case '*':
        return finite(left * right)
      case '/':
        if (right === 0) return DIV0
        return finite(left / right)
      case '^':
        return finite(left ** right)
      default:
        return ERR
    }
  }

  evaluateComparison(node) {
    const left = this.evaluate(node.left)
    if (isError(left)) return left
    const right = this.evaluate(node.right)
    if (isError(right)) return right
    const order = compareValues(left, right)
    let result
    switch (node.op) {
      case '=':
        result = order === 0
        break
      case '<>':
        result = order !== 0
        break
      case '<':
        result = order < 0
        break
      case '<=':
        result = order <= 0
        break
      case '>':
        result = order > 0
        break
      case '>=':
        result = order >= 0
        break
      default:
        return ERR
    }
    return new BoolValue(result)
  }

  evaluateCall(node) {
    if (!Object.prototype.hasOwnProperty.call(ARITY, node.name)) return NAME
    const arity = ARITY[node.name]
    if (arity === null ? node.args.length < 1 : node.args.length !== arity) return ERR
    if (node.name === 'IF') return this.evaluateIf(node)

    const values = []
    for (const arg of node.args) {
      if (arg.type === 'range') {
        const cells = rangeCells(arg)
        if (cells === null) {
          values.push(REF)
          continue
        }
        for (const cell of cells) values.push(this.valueAt(cell.col, cell.row))
      } else {
        values.push(this.evaluate(arg))
      }
    }
    for (const value of values) {
      if (isError(value)) return value
    }
    return applyFunction(node.name, values)
  }

  evaluateIf(node) {
    const condition = toCondition(this.evaluate(node.args[0]))
    if (isError(condition)) return condition
    return this.evaluate(condition ? node.args[1] : node.args[2])
  }
}

function applyFunction(name, values) {
  if (name === 'COUNT') {
    let count = 0
    for (const value of values) {
      if (isNumber(value)) count += 1
    }
    return count
  }
  const numbers = []
  for (const value of values) {
    const number = toNumber(value)
    if (isError(number)) return number
    numbers.push(number)
  }
  switch (name) {
    case 'SUM':
      return finite(numbers.reduce((total, n) => total + n, 0))
    case 'MIN':
      return numbers.reduce((best, n) => (n < best ? n : best))
    case 'MAX':
      return numbers.reduce((best, n) => (n > best ? n : best))
    case 'AVG':
      return finite(numbers.reduce((total, n) => total + n, 0) / numbers.length)
    case 'ABS':
      return finite(Math.abs(numbers[0]))
    default:
      return ERR
  }
}
"}

