/**
 * Formula evaluation engine
 */

import { tokenize, parseAddress, addressToString } from './parser.js';
import { ErrorValue, BooleanValue, toNumber, toBoolean, isError, isNumber, formatValue, parseLiteral } from './types.js';

export class Evaluator {
  constructor(cells) {
    this.cells = cells; // Map of "col,row" -> { content, value, dependencies }
    this.evaluating = new Set(); // Track cells being evaluated (cycle detection)
    this.cache = new Map(); // Cache evaluated values
  }

  evaluateAll() {
    const results = new Map();

    for (const [key, cell] of this.cells) {
      const [colStr, rowStr] = key.split(',');
      const col = parseInt(colStr);
      const row = parseInt(rowStr);
      const value = this.evaluate(col, row);
      results.set(key, value);
    }

    return results;
  }

  evaluate(col, row) {
    const key = `${col},${row}`;

    if (this.cache.has(key)) {
      return this.cache.get(key);
    }

    if (this.evaluating.has(key)) {
      return new ErrorValue('#CYCLE!');
    }

    this.evaluating.add(key);

    const cell = this.cells.get(key);
    let value;

    if (!cell) {
      // Undeclared cell is 0
      value = 0;
    } else if (cell.content.startsWith('=')) {
      // Formula
      value = this.evaluateFormula(cell.content.slice(1));
    } else {
      // Literal
      value = parseLiteral(cell.content);
    }

    this.evaluating.delete(key);
    this.cache.set(key, value);
    return value;
  }

  evaluateFormula(formula) {
    const tokens = tokenize(formula);
    if (tokens === null) {
      return new ErrorValue('#ERR!');
    }

    try {
      const parser = new FormulaParser(tokens, this);
      const [result] = parser.parseComparison();

      if (parser.pos !== tokens.length) {
        return new ErrorValue('#ERR!');
      }

      return result;
    } catch (e) {
      if (e.isFormulaError) {
        return e.value;
      }
      return new ErrorValue('#ERR!');
    }
  }

  getCellValue(col, row) {
    return this.evaluate(col, row);
  }

  getRange(col1, row1, col2, row2) {
    const cells = [];
    const minCol = Math.min(col1, col2);
    const maxCol = Math.max(col1, col2);
    const minRow = Math.min(row1, row2);
    const maxRow = Math.max(row1, row2);

    for (let c = minCol; c <= maxCol; c++) {
      for (let r = minRow; r <= maxRow; r++) {
        cells.push(this.getCellValue(c, r));
      }
    }

    return cells;
  }
}

class FormulaError extends Error {
  constructor(value) {
    super();
    this.isFormulaError = true;
    this.value = value;
  }
}

class FormulaParser {
  constructor(tokens, evaluator) {
    this.tokens = tokens;
    this.evaluator = evaluator;
    this.pos = 0;
  }

  peek() {
    return this.pos < this.tokens.length ? this.tokens[this.pos] : null;
  }

  consume() {
    return this.tokens[this.pos++];
  }

  parseComparison() {
    let [left, isRange] = this.parseAddition();

    if (isRange) {
      throw new FormulaError(new ErrorValue('#ERR!'));
    }

    while (true) {
      const op = this.peek();
      if (!op || op.type !== 'op' || !['=', '<>', '<', '<=', '>', '>='].includes(op.value)) {
        break;
      }

      this.consume();
      const [right, rightIsRange] = this.parseAddition();

      if (rightIsRange) {
        throw new FormulaError(new ErrorValue('#ERR!'));
      }

      left = this.applyComparison(left, op.value, right);
    }

    return [left, false];
  }

  parseAddition() {
    let [left, isRange] = this.parseMultiplication();

    while (true) {
      const op = this.peek();
      if (!op || op.type !== 'op' || !['+', '-'].includes(op.value)) {
        break;
      }

      this.consume();
      const [right, rightIsRange] = this.parseMultiplication();

      left = this.applyOp(left, op.value, right);
      isRange = false;
    }

    return [left, isRange];
  }

  parseMultiplication() {
    let [left, isRange] = this.parseExponentiation();

    while (true) {
      const op = this.peek();
      if (!op || op.type !== 'op' || !['*', '/'].includes(op.value)) {
        break;
      }

      this.consume();
      const [right, rightIsRange] = this.parseExponentiation();

      left = this.applyOp(left, op.value, right);
      isRange = false;
    }

    return [left, isRange];
  }

  parseExponentiation() {
    let [left, isRange] = this.parseUnary();

    if (this.peek() && this.peek().type === 'op' && this.peek().value === '^') {
      this.consume();
      const [right, rightIsRange] = this.parseExponentiation(); // right associative
      left = this.applyOp(left, '^', right);
      isRange = false;
    }

    return [left, isRange];
  }

  parseUnary() {
    const op = this.peek();
    if (op && op.type === 'op' && ['+', '-'].includes(op.value)) {
      this.consume();
      const [operand, isRange] = this.parseUnary();

      if (op.value === '-') {
        const num = toNumber(operand);
        if (isError(num)) {
          return [num, false];
        }
        return [-num, false];
      }

      return [operand, false];
    }

    return this.parsePrimary();
  }

  parsePrimary() {
    const token = this.peek();

    if (!token) {
      throw new FormulaError(new ErrorValue('#ERR!'));
    }

    // Number
    if (token.type === 'number') {
      this.consume();
      return [token.value, false];
    }

    // Word (identifier, function, or cell reference)
    if (token.type === 'word') {
      this.consume();
      const word = token.value;

      // Check for function or cell reference
      if (this.peek() && this.peek().type === 'op' && this.peek().value === '(') {
        // Function call
        return [this.parseFunction(word), false];
      }

      if (this.peek() && this.peek().type === 'op' && this.peek().value === ':') {
        // Range
        const addr1 = parseAddress(word);
        if (!addr1) {
          throw new FormulaError(new ErrorValue('#ERR!'));
        }

        this.consume(); // consume ':'
        const token2 = this.peek();
        if (!token2 || token2.type !== 'word') {
          throw new FormulaError(new ErrorValue('#ERR!'));
        }

        this.consume();
        const addr2 = parseAddress(token2.value);
        if (!addr2) {
          throw new FormulaError(new ErrorValue('#ERR!'));
        }

        return [{ type: 'range', addr1, addr2 }, true];
      }

      // Cell reference or constant
      if (word === 'TRUE') {
        return [new BooleanValue(true), false];
      }
      if (word === 'FALSE') {
        return [new BooleanValue(false), false];
      }

      // Try to parse as address
      const addr = parseAddress(word);
      if (addr) {
        const value = this.evaluator.getCellValue(addr.col, addr.row);
        return [value, false];
      }

      // Unknown word
      throw new FormulaError(new ErrorValue('#NAME?'));
    }

    // Parenthesized expression
    if (token.type === 'op' && token.value === '(') {
      this.consume();
      const [value, isRange] = this.parseComparison();

      if (!this.peek() || this.peek().type !== 'op' || this.peek().value !== ')') {
        throw new FormulaError(new ErrorValue('#ERR!'));
      }

      this.consume();
      return [value, isRange];
    }

    throw new FormulaError(new ErrorValue('#ERR!'));
  }

  parseFunction(name) {
    if (!this.peek() || this.peek().type !== 'op' || this.peek().value !== '(') {
      throw new FormulaError(new ErrorValue('#ERR!'));
    }

    this.consume(); // consume '('

    const args = [];

    if (this.peek() && this.peek().type === 'op' && this.peek().value === ')') {
      this.consume();
      // No arguments
    } else {
      while (true) {
        // Allow ranges in function arguments
        const [arg, isRange] = this.parseFunctionArg();
        args.push({ value: arg, isRange });

        const token = this.peek();
        if (!token || token.type !== 'op' || ![',', ')'].includes(token.value)) {
          throw new FormulaError(new ErrorValue('#ERR!'));
        }

        if (token.value === ')') {
          this.consume();
          break;
        }

        this.consume(); // consume ','
      }
    }

    return this.callFunction(name, args);
  }

  parseFunctionArg() {
    // Same as parseComparison but allows ranges
    let [left, isRange] = this.parseAddition();

    while (true) {
      const op = this.peek();
      if (!op || op.type !== 'op' || !['=', '<>', '<', '<=', '>', '>='].includes(op.value)) {
        break;
      }

      this.consume();
      const [right, rightIsRange] = this.parseAddition();

      if (rightIsRange) {
        throw new FormulaError(new ErrorValue('#ERR!'));
      }

      left = this.applyComparison(left, op.value, right);
      isRange = false;
    }

    return [left, isRange];
  }

  callFunction(name, args) {
    const functions = {
      'SUM': (values) => {
        let sum = 0;
        for (const v of values) {
          const num = toNumber(v);
          if (isError(num)) return num;
          sum += num;
        }
        return sum;
      },
      'MIN': (values) => {
        if (values.length === 0) return new ErrorValue('#ERR!');
        let min = null;
        for (const v of values) {
          const num = toNumber(v);
          if (isError(num)) return num;
          if (min === null || num < min) min = num;
        }
        return min;
      },
      'MAX': (values) => {
        if (values.length === 0) return new ErrorValue('#ERR!');
        let max = null;
        for (const v of values) {
          const num = toNumber(v);
          if (isError(num)) return num;
          if (max === null || num > max) max = num;
        }
        return max;
      },
      'COUNT': (values) => {
        let count = 0;
        for (const v of values) {
          if (typeof v === 'number') count++;
        }
        return count;
      },
      'AVG': (values) => {
        if (values.length === 0) return new ErrorValue('#ERR!');
        let sum = 0;
        for (const v of values) {
          const num = toNumber(v);
          if (isError(num)) return num;
          sum += num;
        }
        return sum / values.length;
      },
      'ABS': (values) => {
        if (values.length !== 1) return new ErrorValue('#ERR!');
        const num = toNumber(values[0]);
        if (isError(num)) return num;
        return Math.abs(num);
      },
      'IF': (values) => {
        if (values.length !== 3) return new ErrorValue('#ERR!');
        const cond = toBoolean(values[0]);
        if (isError(cond)) return cond;
        return cond ? values[1] : values[2];
      }
    };

    if (!(name in functions)) {
      return new ErrorValue('#NAME?');
    }

    // Check argument count for functions that have requirements
    if (['ABS'].includes(name) && args.length !== 1) {
      return new ErrorValue('#ERR!');
    }
    if (['IF'].includes(name) && args.length !== 3) {
      return new ErrorValue('#ERR!');
    }
    if (['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name) && args.length === 0) {
      return new ErrorValue('#ERR!');
    }

    // Expand ranges and collect values
    const values = [];
    for (const arg of args) {
      if (arg.isRange && arg.value.type === 'range') {
        const range = arg.value;
        const rangeValues = this.evaluator.getRange(range.addr1.col, range.addr1.row, range.addr2.col, range.addr2.row);

        // Check for errors in range (first error wins)
        for (const v of rangeValues) {
          if (isError(v)) return v;
        }

        values.push(...rangeValues);
      } else if (arg.isRange && name !== 'IF') {
        // Range in non-function context (but allow in IF)
        if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS'].includes(name)) {
          return new ErrorValue('#ERR!');
        }
      } else {
        // Check for errors in arguments (first error wins)
        if (isError(arg.value)) return arg.value;
        values.push(arg.value);
      }
    }

    return functions[name](values);
  }

  applyOp(left, op, right) {
    if (isError(left)) return left;
    if (isError(right)) return right;

    const leftNum = toNumber(left);
    const rightNum = toNumber(right);

    if (isError(leftNum)) return leftNum;
    if (isError(rightNum)) return rightNum;

    switch (op) {
      case '+': return leftNum + rightNum;
      case '-': return leftNum - rightNum;
      case '*': return leftNum * rightNum;
      case '/':
        if (rightNum === 0) return new ErrorValue('#DIV/0!');
        const result = leftNum / rightNum;
        if (!isFinite(result)) return new ErrorValue('#DIV/0!');
        return result;
      case '^':
        const expResult = Math.pow(leftNum, rightNum);
        if (!isFinite(expResult)) return new ErrorValue('#DIV/0!');
        return expResult;
      default:
        return new ErrorValue('#ERR!');
    }
  }

  applyComparison(left, op, right) {
    if (isError(left)) return left;
    if (isError(right)) return right;

    // Compare values
    let result;

    // Both numbers
    if (typeof left === 'number' && typeof right === 'number') {
      switch (op) {
        case '=': result = left === right; break;
        case '<>': result = left !== right; break;
        case '<': result = left < right; break;
        case '<=': result = left <= right; break;
        case '>': result = left > right; break;
        case '>=': result = left >= right; break;
      }
    }
    // Both text
    else if (typeof left === 'string' && typeof right === 'string') {
      switch (op) {
        case '=': result = left === right; break;
        case '<>': result = left !== right; break;
        case '<': result = left < right; break;
        case '<=': result = left <= right; break;
        case '>': result = left > right; break;
        case '>=': result = left >= right; break;
