  const lines = splitLines(input)
  for (let index = 0; index < lines.length; index++) {
    const lineNumber = index + 1
    const line = lines[index]
    let start = 0
    while (start < line.length && isBlank(line[start])) start += 1
    const rest = line.slice(start)
    if (rest === '' || rest[0] === '#') continue
    let end = 0
    while (end < rest.length && !isBlank(rest[end])) end += 1
    const word = rest.slice(0, end)
    let content = end
    while (content < rest.length && isBlank(rest[content])) content += 1
    const address = parseAddress(word.toUpperCase())
