{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { formatAddress } from './address.js'
import { Sheet } from './evaluator.js'
import { treeReferences } from './formula.js'
import { SheetError, orderedCells, readSheet } from './sheet.js'
import { formatValue } from './values.js'

function fail(message) {
  process.stderr.write(message + '\n')
  process.exit(2)
}

async function readInput() {
  const chunks = []
  for await (const chunk of process.stdin) chunks.push(chunk)
  return Buffer.concat(chunks).toString('utf8')
}

function renderValues(cells) {
  const sheet = new Sheet(cells)
  let out = ''
  for (const cell of orderedCells(cells)) {
    const value = sheet.valueAt(cell.col, cell.row)
    out += `${formatAddress(cell.col, cell.row)}=${formatValue(value)}\n`
  }
  return out
}

function renderDeps(cells) {
  const sheet = new Sheet(cells)
  let out = ''
  for (const cell of orderedCells(cells)) {
    const tree = sheet.treeOf(cell)
    const refs = tree === null ? [] : treeReferences(tree)
    let line = `${formatAddress(cell.col, cell.row)}:`
    for (const ref of refs) line += ' ' + formatAddress(ref.col, ref.row)
    out += line + '\n'
  }
  return out
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
    fail('error: usage: cli.js values|deps')
    return
  }
  const input = await readInput()
  let cells
  try {
    cells = readSheet(input)
  } catch (error) {
    if (error instanceof SheetError) {
      fail(error.message)
      return
    }
    throw error
  }
  const out = args[0] === 'values' ? renderValues(cells) : renderDeps(cells)
  process.stdout.write(out)
}

main()
"}

