import { parseLine, parseAddress, addressToString, tokenize } from './parser.js';
import { Evaluator } from './evaluator.js';
import { formatValue, parseLiteral, ErrorValue, BooleanValue, isError } from './types.js';
import * as readline from 'readline';

async function main() {
  const args = process.argv.slice(2);

  if (args.length !== 1 || !['values', 'deps'].includes(args[0])) {
    process.stderr.write('error: usage: cli.js values|deps\n');
    process.exit(2);
  }

  const mode = args[0];

  // Read all input
  const lines = [];
  const rl = readline.createInterface({
    input: process.stdin,
    output: undefined,
    terminal: false
  });

  for await (const line of rl) {
    lines.push(line);
  }

  // Drop empty tail from trailing newline
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop();
  }

  // Parse all cells
  const cells = new Map(); // key: "col,row"
  const cellOrder = []; // Track insertion order for output

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1;
    const result = parseLine(lines[i], lineNum);

    if (result === null) {
      // Empty line or comment, skip
      continue;
    }

    if (result.error) {
      process.stderr.write(result.error + '\n');
      process.exit(2);
    }

    const { addr, content } = result;
    const key = `${addr.col},${addr.row}`;

    if (cells.has(key)) {
      process.stderr.write(`error: line ${lineNum}: cell ${addr.str} is declared twice\n`);
      process.exit(2);
    }

    cells.set(key, { content, addr });
    cellOrder.push({ col: addr.col, row: addr.row, key });
  }

  // Sort cells for output
  cellOrder.sort((a, b) => {
    if (a.col !== b.col) return a.col - b.col;
    return a.row - b.row;
  });

  if (mode === 'values') {
    // Evaluate all cells
    const evaluator = new Evaluator(cells);

    for (const { col, row, key } of cellOrder) {
      const value = evaluator.evaluate(col, row);
      const addr = addressToString(col, row);
      const formatted = formatValue(value);
      process.stdout.write(`${addr}=${formatted}\n`);
    }
  } else {
    // mode === 'deps'
    // Print dependencies for each cell
    const evaluator = new Evaluator(cells);

    for (const { col, row, key } of cellOrder) {
      const cell = cells.get(key);
      const addr = addressToString(col, row);
      const deps = extractDeps(cell.content, evaluator);

      const depAddrs = Array.from(deps).sort((a, b) => {
        if (a.col !== b.col) return a.col - b.col;
        return a.row - b.row;
      });

      let line = `${addr}:`;
      for (const dep of depAddrs) {
        line += ` ${addressToString(dep.col, dep.row)}`;
      }
      process.stdout.write(line + '\n');
    }
  }

  process.exit(0);
}

function extractDeps(content, evaluator) {
  const deps = new Set();

  if (content.startsWith('=')) {
    const formula = content.slice(1);
    const tokens = tokenize(formula);

    if (tokens === null) {
      // Invalid formula, no deps
      return deps;
    }

    const deps_internal = extractDepsFromTokens(tokens);
    for (const dep of deps_internal) {
      deps.add(dep);
    }
  }

  return deps;
}

function extractDepsFromTokens(tokens) {
  const deps = new Set();

  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];

    if (token.type === 'word') {
      const word = token.value;

      // Check if it's a cell reference (possibly in a range)
      const addr = parseAddress(word);
      if (addr) {
        // Check if it's part of a range
        if (i + 1 < tokens.length && tokens[i + 1].type === 'op' && tokens[i + 1].value === ':') {
          // Range start
          if (i + 2 < tokens.length && tokens[i + 2].type === 'word') {
            const addr2 = parseAddress(tokens[i + 2].value);
            if (addr2) {
              // Add all cells in range
              const minCol = Math.min(addr.col, addr2.col);
              const maxCol = Math.max(addr.col, addr2.col);
              const minRow = Math.min(addr.row, addr2.row);
              const maxRow = Math.max(addr.row, addr2.row);

              for (let c = minCol; c <= maxCol; c++) {
                for (let r = minRow; r <= maxRow; r++) {
                  deps.add({ col: c, row: r });
                }
              }
            }
          }
        } else {
          // Single cell reference
          deps.add(addr);
        }
      }
    }
  }

  return deps;
}

main().catch(err => {
  process.stderr.write('error: ' + err.message + '\n');
  process.exit(2);
});

